import {test} from 'node:test';import assert from 'node:assert/strict';
import {verifyTrivyResult,scanArguments} from './pr356-runtime-scan.mjs';
const imageId='sha256:'+'a'.repeat(64),report=()=>({SchemaVersion:2,Metadata:{ImageID:imageId},Results:[{Target:'os',Vulnerabilities:[]},{Target:'node libraries'}]});
test('structured complete scan of exact image preserves an empty finding set',()=>assert.deepEqual(verifyTrivyResult(report(),imageId).findings,[]));
test('runtime threshold rejects fixable HIGH and CRITICAL without changing ignore-unfixed policy',()=>{for(const severity of ['HIGH','CRITICAL']){const r=report();r.Results[0].Vulnerabilities=[{VulnerabilityID:'CVE-fixture',Severity:severity,FixedVersion:'1.2'}];assert.throws(()=>verifyTrivyResult(r,imageId));}});
test('unfixed and lower findings remain in original result rather than being silently erased',()=>{const r=report();r.Results[0].Vulnerabilities=[{VulnerabilityID:'CVE-unfixed',Severity:'HIGH'},{VulnerabilityID:'CVE-low',Severity:'LOW',FixedVersion:'2'}];assert.equal(verifyTrivyResult(r,imageId).findings.length,2);});
test('missing results, mismatched image and malformed findings cannot produce qualification',()=>{for(const change of [r=>r.Results=[],r=>delete r.Results,r=>r.Metadata.ImageID='sha256:'+'b'.repeat(64),r=>r.Results[0].Vulnerabilities=[{}]]){const r=report();change(r);assert.throws(()=>verifyTrivyResult(r,imageId));}});
test('scanner command consumes immutable original image and retains existing full runtime policy',()=>{const args=scanArguments(imageId,'/owned/out','/owned/cache');assert.equal(args.at(-1),imageId);assert(args.includes('--ignore-unfixed'));assert.equal(args[args.indexOf('--severity')+1],'CRITICAL,HIGH');assert.equal(args[args.indexOf('--vuln-type')+1],'os,library');assert.throws(()=>scanArguments('latest','/x','/y'));});
